const NASA_LOLA_LIMB_720 = NASA_LOLA_LIMB_3600.filter((_, i) => i % 5 === 0);
const NASA_LOLA_DL_720 = NASA_LOLA_DL_3600.filter((_, i) => i % 5 === 0);
const NASA_LOLA_DB_720 = NASA_LOLA_DB_3600.filter((_, i) => i % 5 === 0);

function getLolaLimbElevation(paDeg, libL = 0.4, libB = 0.0, axisC = 14.0) {
    // 1. Ángulo de Watts (V): medido hacia el este desde el polo norte lunar físico
    const vDeg = ((paDeg - axisC) % 360.0 + 360.0) % 360.0;
    const vRad = vDeg * Math.PI / 180.0;

    // 2. PA en el dataset de referencia NASA LOLA (calibrado para 2026 con axisC0 = 14.0°)
    const paRef = (vDeg + 14.0) % 360.0;
    const idxExact = paRef * 10.0;
    const i0 = Math.floor(idxExact) % 3600;
    const i1 = (i0 + 1) % 3600;
    const frac = idxExact - Math.floor(idxExact);
    const h0 = NASA_LOLA_LIMB_3600[i0] * (1.0 - frac) + NASA_LOLA_LIMB_3600[i1] * frac;

    // 3. Proyección física continua de libración lunar (sin amplificación de ruido numérico):
    // La libración en longitud (libL) inclina el limbo Este/Oeste (seno de Watts)
    // La libración en latitud (libB) inclina el limbo Norte/Sur (coseno de Watts)
    const deltaL = (libL != null ? libL : 0.40) - 0.40;
    const deltaB = (libB != null ? libB : 0.00) - 0.00;
    const dL = Math.sin(vRad) * 0.15;
    const dB = Math.cos(vRad) * 0.15;

    return h0 + deltaL * dL + deltaB * dB;
}

